parameters.query:
select o.order_id, o.status, o.eta, o.total
from orders o join identities i on i.type = 'phone' and i.value = o.phone and i.verified
where i.customer_id = $1 and o.status not in ('delivered', 'cancelled');

parameters.jsCode:
const rows = (n) => $(n).all().map(i => i.json).filter(r => Object.keys(r).length);
const timeline = rows('Timeline').reverse().map(m => `${m.at} ${m.channel} ${m.direction === 'in' ? 'customer' : m.sent_by}: ${m.text}`);
return [{ json: { timeline: timeline.join('\n') || 'no earlier messages',
  open_orders: rows('Open orders'), decisions: rows('Decisions') } }];
